// PenguLab bridge protocol 1. Configure PENGULAB_TOKEN in this tab's properties.
// Define only the data points you want to expose. Values arrive on the feedback input.
const definitions = [
    {entity_id:"demo.temperature",name:"Demo Temperatur",value_type:"number",domain:"sensor",unit:"°C",writable:false},
    {entity_id:"demo.switch",name:"Demo Schalter",value_type:"boolean",domain:"switch",writable:true},
    {entity_id:"demo.setpoint",name:"Demo Sollwert",value_type:"number",domain:"number",min:5,max:30,step:0.5,unit:"°C",writable:true},
    {entity_id:"demo.action",name:"Demo Aktion",value_type:"boolean",domain:"button",writable:true}
];
const reply=(status,payload)=>{msg.statusCode=status;msg.headers={"Content-Type":"application/json","Cache-Control":"no-store"};msg.payload=payload;return [msg,null];};
const token=env.get("PENGULAB_TOKEN");
if(typeof token!=="string"||token.length<16)return reply(503,{ok:false,error:"Set PENGULAB_TOKEN (at least 16 characters) in flow properties."});
if(msg.req.headers.authorization!=="Bearer "+token)return reply(401,{ok:false,error:"Unauthorized"});
const op=msg.req.method==="POST"?"action":msg.req.params.operation;
if(op==="health")return reply(200,{ok:true,protocol:1});
if(op==="entities"){
    const values=flow.get("pengulabValues")||{};
    const entities=definitions.map(e=>{
        const known=Object.prototype.hasOwnProperty.call(values,e.entity_id),v=known?values[e.entity_id]:null;
        return {...e,value:v,state:!known||v===null?"unavailable":typeof v==="boolean"?(v?"on":"off"):String(v)};
    });
    return reply(200,{ok:true,entities});
}
if(op!=="action"||msg.req.method!=="POST")return reply(404,{ok:false,error:"Unknown operation"});
const p=msg.payload;
if(!p||typeof p!=="object"||Array.isArray(p))return reply(400,{ok:false,error:"JSON object required"});
const e=definitions.find(e=>e.entity_id===p.entity_id);
if(!e||!e.writable)return reply(403,{ok:false,error:"Data point is not writable"});
let value=p.value;
if(e.domain==="button"){
    if(p.action!=="trigger")return reply(400,{ok:false,error:"Use trigger"});value=true;
}else{
    if(p.action!=="set")return reply(400,{ok:false,error:"Use set"});
    if(e.value_type==="boolean"&&typeof value!=="boolean")return reply(400,{ok:false,error:"Boolean required"});
    if(e.value_type==="number"&&(typeof value!=="number"||!Number.isFinite(value)||(e.min!==undefined&&value<e.min)||(e.max!==undefined&&value>e.max)))return reply(400,{ok:false,error:"Invalid numeric value"});
}
// Output 2 is the command. Connect it to your existing automation nodes.
// Device feedback updates the displayed value; accepting a command is not a device acknowledgement.
const result=reply(202,{ok:true,accepted:true});
result[1]={topic:e.entity_id,payload:value,penguLabAction:p.action};
return result;

// Feed real device values into this node: msg.topic = entity_id, msg.payload = value.
if(typeof msg.topic!=="string"||!["string","number","boolean"].includes(typeof msg.payload)&&msg.payload!==null)return null;
if(["__proto__","constructor","prototype"].includes(msg.topic))return null;
const values=flow.get("pengulabValues")||{};
values[msg.topic]=msg.payload;
flow.set("pengulabValues",values);
return null;
